import {expect as baseExpect} from '@playwright/test'
import {randomUUID,randomBytes} from 'node:crypto'
import {writeFileSync,mkdirSync} from 'node:fs'
import {prepareConcerns} from './concerns.mjs'
import {expectSuccess} from '../../scripts/staging/assertions.mjs'
const expect=baseExpect.configure({timeout:30000})
export async function deviceDraftWorkflow({browser,origin,actors,options={},record=()=>{}}){
 const f=await prepareConcerns(actors,'SYNTHETIC device recovery'),contexts=[];let stage='setup'
 const rpc=(role,fn,command,p)=>actors[role].client.rpc(fn,{command,p:{companyId:f.company,requestId:randomUUID(),...p}}).then(expectSuccess)
 const row=async(table,id)=>(expectSuccess(await actors[table==='ts_concerns'?'WORKER':'OWNER'].client.from(table).select('*').eq('id',id).single()))
 async function context(state){const {localOnly,...settings}=options,c=await browser.newContext({viewport:{width:390,height:844},...settings,...(state?{storageState:state}:{})});contexts.push(c);if(localOnly)await c.route('**/*',r=>[origin,actors.WORKER.apiOrigin].includes(new URL(r.request().url()).origin)?r.continue():r.abort());return c}
 async function page(c,role='WORKER'){const p=await c.newPage();p.setDefaultTimeout(30000);p.setDefaultNavigationTimeout(90000);await p.goto(origin+'/auth/login');await p.getByLabel('Email',{exact:true}).fill(actors[role].email);await p.getByLabel('Password',{exact:true}).fill(actors[role].password);await p.getByRole('button',{name:'Sign In',exact:true}).click();await p.waitForURL('**/dashboard');return p}
 const local=p=>p.evaluate(()=>Object.keys(localStorage).filter(k=>k.startsWith('tradesafe.device-text.v1:')).map(k=>JSON.parse(localStorage.getItem(k))))
 try{
  let c=await context(),p=await page(c);await page(await context(),'SUPERVISOR')
  stage='unsent-concern';await p.goto(origin+'/concerns/new?site='+f.siteId);const opt=p.getByLabel('Keep unfinished text on this device',{exact:true});await expect(opt).toBeEnabled();await opt.check();await opt.focus();await expect(opt).toBeFocused()
  await c.route('**/api/concerns',r=>r.abort());await p.getByLabel('What did you observe?',{exact:true}).fill('SYNTHETIC recover after browser closes');await p.getByLabel('Where on this site?',{exact:true}).fill('SYNTHETIC east bay');await expect(p.getByRole('status').filter({hasText:'Saved on this device; upload pending'})).toBeVisible()
  const saved=(await local(p))[0],id=saved.id,url=p.url();expect(saved.text.location).toBe('SYNTHETIC east bay');expect(saved.revision).toBe(0)
  await p.getByRole('button',{name:'Save concern draft',exact:true}).click();await expect(p.getByRole('alert').filter({hasText:'No completion was confirmed'})).toBeVisible();expect((await local(p))[0].text.observation).toBe(saved.text.observation)
  stage='context-restart';const state=await c.storageState();await c.close();c=await context(state);p=await c.newPage();p.setDefaultTimeout(30000);p.setDefaultNavigationTimeout(90000);await p.goto(url);await expect(p.getByRole('heading',{name:'Recover unfinished text',exact:true})).toBeVisible();await p.getByRole('button',{name:'Use device text in current draft',exact:true}).click();await expect(p.getByLabel('Where on this site?',{exact:true})).toHaveValue(saved.text.location)
  await p.getByRole('button',{name:'Save concern draft',exact:true}).click();await expect(p.getByRole('status').filter({hasText:'Saved concern draft'})).toBeVisible();expect((await row('ts_concerns',id)).document.observation).toBe(saved.text.observation);await expect.poll(()=>local(p).catch(()=>['navigation pending'])).toHaveLength(0)
  stage='lost-committed-response';await p.getByLabel('What did you observe?',{exact:true}).fill('SYNTHETIC lost response retained');let lost=false;await c.route('**/api/concerns',async r=>{if(!lost){lost=true;expect((await r.fetch()).status()).toBe(200);await r.abort()}else await r.continue()});await p.getByRole('button',{name:'Save concern draft',exact:true}).click();await expect(p.getByRole('button',{name:'Retry same concern operation',exact:true})).toBeVisible();await p.reload();await expect(p.getByRole('heading',{name:'Server changes require review',exact:true})).toBeVisible();await p.getByRole('button',{name:'Use device text in current draft',exact:true}).click();await p.getByRole('button',{name:'Save concern draft',exact:true}).click();await expect(p.getByRole('status').filter({hasText:'Saved concern draft'})).toBeVisible();await c.unroute('**/api/concerns');expect((await row('ts_concerns',id)).document.observation).toBe('SYNTHETIC lost response retained');expect(expectSuccess(await actors.WORKER.client.from('ts_concerns').select('id').eq('id',id))).toHaveLength(1)
  stage='brief-conflict';const b=await rpc('WORKER','ts_brief_command','create',{id:randomUUID()});await p.goto(origin+'/briefs/'+b.id+'?step=2');await expect(p.getByLabel('Keep unfinished text on this device')).toBeEnabled();await p.getByLabel('Keep unfinished text on this device').check();await c.route('**/api/briefs',r=>r.abort());await p.locator('#brief-task').fill('SYNTHETIC local task');await p.getByRole('button',{name:'Continue',exact:true}).click();await p.getByRole('button',{name:'Add task step and hazard',exact:true}).click();await p.getByLabel('Task step',{exact:true}).fill('SYNTHETIC local step');await p.getByLabel('Hazard or concern',{exact:true}).fill('SYNTHETIC local hazard');await p.getByLabel('Control or precaution',{exact:true}).fill('SYNTHETIC local control');expect((await local(p))[0].text.steps[0].control).toBe('SYNTHETIC local control')
  const latest=await row('ts_briefs',b.id);await rpc('SUPERVISOR','ts_brief_command','save',{id:b.id,revision:latest.revision,document:{...latest.document,task:'SYNTHETIC second device version'}});await p.reload();await expect(p.getByRole('heading',{name:'Server changes require review',exact:true})).toBeVisible();expect((await row('ts_briefs',b.id)).document.task).toBe('SYNTHETIC second device version');await c.unroute('**/api/briefs');await p.getByRole('button',{name:'Use device text in current draft',exact:true}).click();await expect(p.locator('.save-state')).toHaveText('Saved to server');const reconciled=await row('ts_briefs',b.id);expect(reconciled.document.task).toBe('SYNTHETIC local task');expect(reconciled.document.steps[0].control).toBe('SYNTHETIC local control');expect(reconciled.document.steps[0].controlState).toBe('proposed');expect(reconciled.document.attendance).toHaveLength(0)
  stage='disabled-storage';await c.route('**/api/briefs',r=>r.abort());await p.evaluate(()=>{window.originalDeviceGet=Storage.prototype.getItem;window.deniedDeviceSet=Storage.prototype.setItem;Storage.prototype.setItem=function(k,v){if(k.startsWith('tradesafe.device-text.v1:'))throw new DOMException('blocked','SecurityError');return window.deniedDeviceSet.call(this,k,v)};Storage.prototype.getItem=function(k){if(k.startsWith('tradesafe.device-text.v1:'))throw new DOMException('blocked','SecurityError');return window.originalDeviceGet.call(this,k)}});await p.getByLabel('Hazard or concern',{exact:true}).fill('SYNTHETIC visible with blocked storage');await expect(p.getByRole('alert').filter({hasText:'Device storage is blocked'})).toBeVisible();await expect(p.getByLabel('Hazard or concern',{exact:true})).toHaveValue('SYNTHETIC visible with blocked storage');await p.evaluate(()=>{Storage.prototype.getItem=window.originalDeviceGet;Storage.prototype.setItem=window.deniedDeviceSet});
  stage='denied-storage';await p.evaluate(()=>{window.originalDeviceSet=Storage.prototype.setItem;Storage.prototype.setItem=function(k,v){if(k.startsWith('tradesafe.device-text.v1:'))throw new DOMException('full','QuotaExceededError');return window.originalDeviceSet.call(this,k,v)}});await c.route('**/api/briefs',r=>r.abort());await p.getByLabel('Hazard or concern',{exact:true}).fill('SYNTHETIC visible despite quota');await expect(p.getByRole('alert').filter({hasText:'browser storage is full'})).toBeVisible();await expect(p.getByLabel('Hazard or concern',{exact:true})).toHaveValue('SYNTHETIC visible despite quota');await p.evaluate(()=>{Storage.prototype.setItem=window.originalDeviceSet});await p.getByLabel('Hazard or concern',{exact:true}).fill('SYNTHETIC stored after quota');await expect.poll(async()=>(await local(p))[0]?.text.steps[0].hazard).toBe('SYNTHETIC stored after quota')
  stage='expired-session';await c.clearCookies();await p.goto(origin+'/briefs/'+b.id+'?step=3');await expect(p).toHaveURL(/auth\/login/);expect((await local(p))[0].text.steps[0].hazard).toBe('SYNTHETIC stored after quota');p=await page(c,'WORKER');await p.goto(origin+'/briefs/'+b.id+'?step=3');await p.getByRole('button',{name:'Use device text in current draft',exact:true}).click();await expect(p.getByLabel('Hazard or concern',{exact:true})).toHaveValue('SYNTHETIC stored after quota');
  stage='opt-out';p.once('dialog',d=>d.accept());await p.getByLabel('Keep unfinished text on this device').uncheck();expect(await local(p)).toHaveLength(0);await expect(p.getByLabel('Hazard or concern',{exact:true})).toHaveValue('SYNTHETIC stored after quota');await p.getByLabel('Keep unfinished text on this device').check();
  stage='pending-list';await p.goto(origin+'/device-drafts?company='+f.company);await expect(p.getByRole('link',{name:'Review device text',exact:true})).toBeVisible();expect(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true)
  stage='cross-company-revoked';const api=origin+'/api/device-drafts?'+new URLSearchParams({company:f.company,kind:'brief',id:b.id});const outsider=await page(await context(),'OUTSIDER');expect((await outsider.context().request.get(api,{headers:{'X-Expected-Actor':actors.OUTSIDER.id}})).status()).toBe(403);await rpc('OWNER','ts_command','member',{userId:actors.WORKER.id,role:'remove'});await p.getByRole('button',{name:'Check device drafts again',exact:true}).click();await expect(p.getByText('No recoverable device drafts for your account in this company.',{exact:true})).toBeVisible();expect((await c.request.get(api,{headers:{'X-Expected-Actor':actors.WORKER.id}})).status()).toBe(403)
  // Restore only this task-owned synthetic membership, through the ordinary owner invitation flow.
  stage='restore-synthetic-membership';const token=randomBytes(32).toString('hex');await rpc('OWNER','ts_command','invite',{email:actors.WORKER.email,role:'worker',token});await rpc('WORKER','ts_command','accept_invitation',{token});await p.goto(origin+'/device-drafts?company='+f.company);await expect(p.getByText('No recoverable device drafts for your account in this company.',{exact:true})).toBeVisible()
  stage='expiry-corruption';await p.evaluate(v=>{const key='tradesafe.device-text.v1:'+ [v.actor,v.company,v.kind,v.id].join(':');localStorage.setItem(key,JSON.stringify({...v,savedAt:Date.now()-8*86400000}));localStorage.setItem('tradesafe.device-text.v1:broken','unreadable')},saved);await p.reload();await expect(p.getByText('No recoverable device drafts for your account in this company.',{exact:true})).toBeVisible();expect(await local(p)).toHaveLength(0);
  stage='account-switch';await p.goto(origin+'/concerns/'+id);await p.getByLabel('Keep unfinished text on this device').check();await p.getByLabel('Where on this site?',{exact:true}).fill('SYNTHETIC switch-account text');const switched=await page(c,'SUPERVISOR');await expect.poll(()=>local(switched).catch(()=>['navigation pending'])).toHaveLength(0);p=await page(c,'WORKER');
  stage='logout-return-to-concern';await p.goto(origin+'/concerns/'+id)
  stage='logout-device-opt-in';await p.getByLabel('Keep unfinished text on this device').check()
  stage='logout-edit';await p.getByLabel('Where on this site?',{exact:true}).fill('SYNTHETIC logout text')
  stage='logout-command';p.once('dialog',d=>d.accept());await p.getByRole('button',{name:'Sign out',exact:true}).click()
  stage='logout-cleanup';await expect.poll(()=>local(p).catch(()=>['navigation pending'])).toHaveLength(0)
  record('PASS actual device storage, context restart, server values, explicit conflicts, response loss, quota, role checks and cleanup',{...f,concernId:id,briefId:b.id})
 }catch(e){mkdirSync('test-results',{recursive:true});writeFileSync('test-results/device-drafts-stage.json',JSON.stringify({stage,error:e.name,assertion:e.matcherResult?.name||null}));throw e}finally{for(const c of contexts)await c.close()}
}
